package ec.edu.espe.appdistclient.interfaz.cuentasporcobrar;
import java.awt.*; import javax.swing.*; import javax.swing.table.*;
final class TemaCxc {
 static final Color BG=new Color(238,240,243), PANEL=Color.WHITE, DARK=new Color(38,40,44), TEXT=new Color(20,20,20), BORDER=new Color(205,208,213), ACCENT=new Color(75,83,94);
 static final Font FONT=new Font("Tahoma",Font.PLAIN,12), BOLD=new Font("Tahoma",Font.BOLD,12);
 static void apply(JFrame f){ f.getContentPane().setBackground(BG); walk(f.getContentPane()); }
 static void walk(Component c){ if(c instanceof JPanel p){p.setBackground(PANEL);} if(c instanceof JLabel l){l.setForeground(TEXT); if(l.getFont().getSize()<18)l.setFont(FONT);} if(c instanceof JTextField t){t.setFont(FONT);t.setForeground(TEXT);} if(c instanceof JTextArea t){t.setFont(FONT);t.setForeground(TEXT);} if(c instanceof JComboBox<?> b){b.setFont(FONT);b.setForeground(TEXT);} if(c instanceof JButton b){b.setFont(BOLD);b.setForeground(Color.WHITE);String s=b.getText().toLowerCase();b.setBackground(s.contains("eliminar")?new Color(145,48,48):s.contains("guardar")||s.contains("registrar")?new Color(48,55,64):ACCENT);b.setFocusPainted(false);b.setBorder(BorderFactory.createEmptyBorder(7,12,7,12));b.setOpaque(true);} if(c instanceof JTable t){t.setFont(FONT);t.setForeground(TEXT);t.setRowHeight(26);t.setGridColor(new Color(225,227,230));t.setSelectionBackground(new Color(218,222,228));t.setSelectionForeground(TEXT); JTableHeader h=t.getTableHeader();h.setFont(BOLD);h.setBackground(new Color(224,227,231));h.setForeground(TEXT);h.setOpaque(true);} if(c instanceof Container x)for(Component child:x.getComponents())walk(child); }
 static JPanel header(String title,String subtitle){ JPanel p=new JPanel(new BorderLayout());p.setBackground(DARK);p.setBorder(BorderFactory.createEmptyBorder(13,20,13,20));JLabel a=new JLabel(title);a.setForeground(Color.WHITE);a.setFont(new Font("Tahoma",Font.BOLD,19));JLabel b=new JLabel(subtitle);b.setForeground(new Color(225,227,230));b.setFont(new Font("Tahoma",Font.PLAIN,11));JPanel x=new JPanel(new GridLayout(2,1));x.setOpaque(false);x.add(a);x.add(b);p.add(x,BorderLayout.WEST);return p; }
 static void finish(JFrame f,int w,int h){apply(f);f.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);f.setSize(w,h);f.setMinimumSize(new Dimension(Math.min(w,760),Math.min(h,520)));f.setLocationRelativeTo(null);}
 static void error(Component c,String msg){JOptionPane.showMessageDialog(c,msg,"Cuentas por Cobrar",JOptionPane.ERROR_MESSAGE);}
 static void info(Component c,String msg){JOptionPane.showMessageDialog(c,msg,"Cuentas por Cobrar",JOptionPane.INFORMATION_MESSAGE);}
}
